"""A small integer/float arithmetic expression evaluator.

Supported grammar (lowest precedence first)::

    expr   := term (("+" | "-") term)*                  # left associative
    term   := factor (("*" | "/" | "//" | "%") factor)* # left associative
    factor := ("+" | "-") factor | power                # unary, repeatable
    power  := atom ["**" factor]                        # right associative
    atom   := INTEGER | "(" expr ")"

Because ``factor`` sits between ``term`` and ``power``, unary operators bind
more tightly than ``*`` and friends but less tightly than ``**``; hence
``-2 ** 2 == -4`` while ``(-2) ** 2 == 4``.

The evaluator is written by hand: no ``eval``, ``exec``, ``ast`` or ``compile``.
"""

from __future__ import annotations

__all__ = ["evaluate"]

# --------------------------------------------------------------------------
# Tokenizer
# --------------------------------------------------------------------------

# Token kinds.
NUMBER = "NUMBER"
OP = "OP"
LPAREN = "LPAREN"
RPAREN = "RPAREN"
EOF = "EOF"

# Multi-character operators must be tried before their single-character
# prefixes, so the order of this tuple matters.
_OPERATORS = ("**", "//", "+", "-", "*", "/", "%")

_DIGITS = "0123456789"


class _Token:
    __slots__ = ("kind", "text", "pos")

    def __init__(self, kind: str, text: str, pos: int) -> None:
        self.kind = kind
        self.text = text
        self.pos = pos

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return "_Token(%r, %r, %r)" % (self.kind, self.text, self.pos)


def _tokenize(text: str) -> list:
    """Split *text* into tokens, raising ValueError on unknown characters."""
    tokens = []
    i = 0
    length = len(text)
    while i < length:
        char = text[i]

        # Any whitespace (spaces, tabs, newlines, ...) separates tokens.
        if char.isspace():
            i += 1
            continue

        if char in _DIGITS:
            start = i
            while i < length and text[i] in _DIGITS:
                i += 1
            # A digit run immediately followed by '.' or a letter is not a
            # valid decimal integer literal (e.g. "1.5", "1e3", "0x10").
            if i < length and (text[i] == "." or text[i] == "_" or text[i].isalnum()):
                raise ValueError(
                    "invalid numeric literal at position %d: %r"
                    % (start, text[start : i + 1])
                )
            tokens.append(_Token(NUMBER, text[start:i], start))
            continue

        if char == "(":
            tokens.append(_Token(LPAREN, char, i))
            i += 1
            continue

        if char == ")":
            tokens.append(_Token(RPAREN, char, i))
            i += 1
            continue

        for operator in _OPERATORS:
            if text.startswith(operator, i):
                tokens.append(_Token(OP, operator, i))
                i += len(operator)
                break
        else:
            raise ValueError("unexpected character %r at position %d" % (char, i))

    tokens.append(_Token(EOF, "", length))
    return tokens


# --------------------------------------------------------------------------
# Parser -> tiny AST
# --------------------------------------------------------------------------
#
# Nodes are plain tuples:
#   ("num",   int_value)
#   ("unary", op, operand_node)
#   ("bin",   op, left_node, right_node)


class _Parser:
    def __init__(self, tokens: list) -> None:
        self._tokens = tokens
        self._index = 0

    # -- helpers ----------------------------------------------------------
    @property
    def _current(self) -> _Token:
        return self._tokens[self._index]

    def _advance(self) -> _Token:
        token = self._tokens[self._index]
        self._index += 1
        return token

    def _at_operator(self, *names: str) -> bool:
        token = self._current
        return token.kind == OP and token.text in names

    @staticmethod
    def _describe(token: _Token) -> str:
        if token.kind == EOF:
            return "end of input"
        return "%r at position %d" % (token.text, token.pos)

    # -- grammar rules ----------------------------------------------------
    def parse(self):
        node = self.parse_expr()
        if self._current.kind != EOF:
            raise ValueError("unexpected %s" % self._describe(self._current))
        return node

    def parse_expr(self):
        node = self.parse_term()
        while self._at_operator("+", "-"):
            op = self._advance().text
            node = ("bin", op, node, self.parse_term())
        return node

    def parse_term(self):
        node = self.parse_factor()
        while self._at_operator("*", "/", "//", "%"):
            op = self._advance().text
            node = ("bin", op, node, self.parse_factor())
        return node

    def parse_factor(self):
        if self._at_operator("+", "-"):
            op = self._advance().text
            return ("unary", op, self.parse_factor())
        return self.parse_power()

    def parse_power(self):
        base = self.parse_atom()
        if self._at_operator("**"):
            self._advance()
            # Right associative, and the exponent may carry unary signs.
            return ("bin", "**", base, self.parse_factor())
        return base

    def parse_atom(self):
        token = self._current
        if token.kind == NUMBER:
            self._advance()
            return ("num", int(token.text))
        if token.kind == LPAREN:
            self._advance()
            if self._current.kind == RPAREN:
                raise ValueError("empty parentheses at position %d" % token.pos)
            node = self.parse_expr()
            if self._current.kind != RPAREN:
                raise ValueError(
                    "expected ')' but found %s" % self._describe(self._current)
                )
            self._advance()
            return node
        raise ValueError("expected an operand but found %s" % self._describe(token))


# --------------------------------------------------------------------------
# Evaluation
# --------------------------------------------------------------------------


def _apply(op: str, left, right):
    if op == "+":
        return left + right
    if op == "-":
        return left - right
    if op == "*":
        return left * right
    if op == "/":
        if right == 0:
            raise ZeroDivisionError("division by zero")
        return left / right
    if op == "//":
        if right == 0:
            raise ZeroDivisionError("integer division or modulo by zero")
        return left // right
    if op == "%":
        if right == 0:
            raise ZeroDivisionError("integer division or modulo by zero")
        return left % right
    if op == "**":
        if right < 0:
            raise ValueError("negative exponent is not supported")
        return left**right
    raise ValueError("unknown operator %r" % op)  # pragma: no cover - defensive


def _eval(node):
    kind = node[0]
    if kind == "num":
        return node[1]
    if kind == "unary":
        value = _eval(node[2])
        return -value if node[1] == "-" else +value
    # kind == "bin"
    return _apply(node[1], _eval(node[2]), _eval(node[3]))


def evaluate(text):
    """Evaluate the arithmetic expression *text* and return an int or float.

    Raises ``ValueError`` for malformed input (including a negative exponent)
    and ``ZeroDivisionError`` for division or modulo by zero.
    """
    if not isinstance(text, str):
        raise TypeError("expression must be a string, not %s" % type(text).__name__)

    tokens = _tokenize(text)
    if len(tokens) == 1:  # only EOF
        raise ValueError("empty expression")

    tree = _Parser(tokens).parse()
    return _eval(tree)

